import logging
import subprocess
from taf.analyzer.pdml import PdmlReader


class TsharkReader(PdmlReader):

    def __init__(self, tshark_command, **kwargs):
        self._tshark_command = tshark_command
        super(TsharkReader, self).__init__(file_obj=None, **kwargs)
        self._file_obj = self._stdout_readlines()

    def _stdout_readlines(self):
        logging.info("start reading packets with command={}".format(self._tshark_command))

        tshark_process = subprocess.Popen(str(self._tshark_command), stdout=subprocess.PIPE, shell=True)
        for line in tshark_process.stdout:
            yield line
        tshark_process.terminate()
